/// An exact submission and its final host observation. An error is not GPU
/// completion; the context continues to retain possibly reachable resources.
pub struct RuntimeAsyncOperationResultV1<A, E> {
    /// Absent only when launch returned no usable submission handle.
    pub submission: Option<RuntimeSubmissionV1<A>>,
    pub observation: Result<RuntimeCompletionStatusV1, RuntimeErrorV1<E>>,
    pub rejected_observations: u64,
    pub last_rejected_observation: Option<E>,
}

/// Standard future for runtime-owned submission, progress, and observation.
///
/// Dropping it does not cancel the operation or withdraw its progress. A stopped
/// engine is not evidence of non-publication or quiescence. Completion does not
/// release the submission, allocations, or module; use ordinary context release
/// APIs after inspecting the outcome, or inspect owner shutdown's cleanup report.
pub type RuntimeAsyncOperationFutureV1<A, E> =
    RuntimeAsyncCommandFutureV1<RuntimeAsyncOperationResultV1<A, E>>;

/// Owner-local driver installed before its first Context/native effect.
pub(super) trait EngineOperationV1<B: RuntimeBackendV1> {
    /// True grants driver disposal, not merely completion of its reply. Issued
    /// custody must remain here or in the Context until conclusively retired.
    fn advance(&mut self, context: &mut RuntimeContextV1<B>) -> bool;
    /// Inert flush identity, cached before first advance. Preparation has none.
    fn stream(&self) -> Option<RuntimeStreamIdV1>;
    /// Only a fully host-owned, never-adopted preparation may park.
    fn prepared_key(&self) -> Option<&Arc<generated_operation::PreparedKeyV1>> {
        None
    }
    fn reserved_key(&self) -> Option<&Arc<generated_operation::PreparedKeyV1>> {
        None
    }
    fn reserve_generated(
        &mut self,
        _context: &mut RuntimeContextV1<B>,
        _completion: &mut Option<owned::Reply<()>>,
    ) -> Result<(), crate::RuntimeGfx942GeneratedReservationErrorV1> {
        Err(crate::RuntimeGfx942GeneratedReservationErrorV1::UnsupportedPreparation)
    }
    fn preflight_adoption(
        &mut self,
        _context: &mut RuntimeContextV1<B>,
        _stream: RuntimeStreamIdV1,
    ) -> Result<(), RuntimeErrorV1<B::Error>> {
        Err(crate::RuntimeValidationErrorV1::Unsupported.into())
    }
    fn activate_adoption(
        &mut self,
        _hold: crate::context::ContextUnpublishedHoldV1,
        _ticket: RuntimeAsyncReservedTicketV1,
    ) {
        unreachable!("only an admitted generated driver activates")
    }
    /// True permits disposal only after exact unpublished native retirement.
    fn retire_unpublished(
        &mut self,
        _context: &mut RuntimeContextV1<B>,
    ) -> Result<bool, RuntimeErrorV1<B::Error>> {
        Ok(false)
    }
    /// Called after the driver is rooted in the preallocated parked roster.
    fn complete_preparation(&mut self) {}
    /// Infallibly detach/resolve the reply before any fallible handling, without
    /// disposing possibly reachable native custody. Panic containment preserves
    /// custody, but cannot recover a reply hidden by a broken implementation.
    fn reject(&mut self, error: RuntimeAsyncEngineCallErrorV1);
}

struct OperationEntryV1<B: RuntimeBackendV1> {
    stream: Option<RuntimeStreamIdV1>,
    driver: Box<dyn EngineOperationV1<B>>,
}

pub(super) struct OperationRegistryV1<B: RuntimeBackendV1> {
    entries: VecDeque<OperationEntryV1<B>>,
    parked: VecDeque<OperationEntryV1<B>>,
    streams: BTreeMap<RuntimeStreamIdV1, usize>,
    flush_cursor: Option<RuntimeStreamIdV1>,
    owner_cleanup: bool,
}

impl<B: RuntimeBackendV1> OperationRegistryV1<B> {
    pub(super) fn new(capacity: usize, owner_cleanup: bool) -> Self {
        Self {
            entries: VecDeque::with_capacity(capacity),
            parked: VecDeque::with_capacity(capacity),
            streams: BTreeMap::new(),
            flush_cursor: None,
            owner_cleanup,
        }
    }

    pub(super) fn len(&self) -> usize {
        self.entries.len() + self.parked.len()
    }

    pub(super) fn active_len(&self) -> usize {
        self.entries.len()
    }

    pub(super) fn insert(&mut self, operation: Box<dyn EngineOperationV1<B>>) {
        let stream = operation.stream();
        if let Some(stream) = stream {
            *self.streams.entry(stream).or_default() += 1;
        }
        self.entries.push_back(OperationEntryV1 {
            stream,
            driver: operation,
        });
    }

    pub(super) fn accepts_factory(&self, factory: &dyn EngineOperationFactoryV1<B>) -> bool {
        self.owner_cleanup || !factory.requires_owned_shutdown()
    }

    /// Resolving a reply never removes its driver from the custody roster.
    pub(super) fn stop_observations(&mut self) -> bool {
        let mut panicked = false;
        for entry in self.entries.iter_mut().chain(&mut self.parked) {
            if let Err(payload) = catch_unwind(AssertUnwindSafe(|| {
                entry
                    .driver
                    .reject(RuntimeAsyncEngineCallErrorV1::EngineStopped);
            })) {
                core::mem::forget(payload);
                panicked = true;
            }
        }
        panicked
    }

    fn retire_stream(&mut self, stream: Option<RuntimeStreamIdV1>) {
        let Some(stream) = stream else { return };
        let count = self
            .streams
            .get_mut(&stream)
            .expect("operation stream is retained");
        *count -= 1;
        if *count == 0 {
            self.streams.remove(&stream);
        }
    }

    pub(super) fn discard_prepared(
        &mut self,
        key: &Arc<generated_operation::PreparedKeyV1>,
    ) -> bool {
        self.discard_parked(key, false)
    }

    pub(super) fn discard_reserved(
        &mut self,
        key: &Arc<generated_operation::PreparedKeyV1>,
    ) -> bool {
        self.discard_parked(key, true)
    }

    fn discard_parked(
        &mut self,
        key: &Arc<generated_operation::PreparedKeyV1>,
        reserved: bool,
    ) -> bool {
        let Some(index) = self.parked.iter().position(|entry| {
            (if reserved {
                entry.driver.reserved_key()
            } else {
                entry.driver.prepared_key()
            })
            .is_some_and(|stored| Arc::ptr_eq(stored, key))
        }) else {
            return false;
        };
        // The caller contains destructor panic and owns the discard reply.
        drop(self.parked.remove(index).expect("matched parked owner"));
        true
    }

    pub(super) fn reserve_generated(
        &mut self,
        context: &mut RuntimeContextV1<B>,
        key: &Arc<generated_operation::PreparedKeyV1>,
        completion: &mut Option<owned::Reply<()>>,
    ) -> Result<(), crate::RuntimeGfx942GeneratedReservationErrorV1> {
        let entry = self
            .parked
            .iter_mut()
            .find(|entry| {
                entry
                    .driver
                    .prepared_key()
                    .is_some_and(|stored| Arc::ptr_eq(stored, key))
            })
            .ok_or(crate::RuntimeGfx942GeneratedReservationErrorV1::Engine(
                RuntimeAsyncEngineCallErrorV1::InvalidPreparedTicket,
            ))?;
        entry.driver.reserve_generated(context, completion)
    }

    pub(super) fn activate_reserved(
        &mut self,
        context: &mut RuntimeContextV1<B>,
        ticket: &mut Option<RuntimeAsyncReservedTicketV1>,
        stream: RuntimeStreamIdV1,
    ) -> Result<(), generated_operation::adoption::ActivationErrorV1<B::Error>> {
        use generated_operation::adoption::ActivationErrorV1 as Error;
        if context.is_terminal() || !self.owner_cleanup {
            return Err(Error::Engine(RuntimeAsyncEngineCallErrorV1::EngineStopped));
        }
        let key = &ticket.as_ref().expect("queued reserved ticket").key;
        if key.context_generation != context.capture_context_generation_v1() {
            return Err(Error::Engine(
                RuntimeAsyncEngineCallErrorV1::InvalidPreparedTicket,
            ));
        }
        let index = self
            .parked
            .iter()
            .position(|entry| {
                entry
                    .driver
                    .reserved_key()
                    .is_some_and(|stored| Arc::ptr_eq(stored, key))
            })
            .ok_or(Error::Engine(
                RuntimeAsyncEngineCallErrorV1::InvalidPreparedTicket,
            ))?;
        if self.entries.len() == self.entries.capacity() {
            return Err(Error::Engine(
                RuntimeAsyncEngineCallErrorV1::OperationCapacity,
            ));
        }
        self.parked[index]
            .driver
            .preflight_adoption(context, stream)
            .map_err(Error::Context)?;
        let hold = context
            .hold_unpublished_stream_v1(stream)
            .map_err(|error| Error::Context(error.into()))?;
        let entry = self.parked.remove(index).expect("exact parked entry");
        debug_assert!(
            entry.stream.is_none(),
            "adoption never enters the flush roster"
        );
        self.entries.push_back(entry);
        // Root the same driver before its phase changes or any adapter effect.
        self.entries
            .back_mut()
            .expect("rooted adoption")
            .driver
            .activate_adoption(hold, ticket.take().expect("consumed exact reserved ticket"));
        Ok(())
    }

    pub(super) fn retire_unpublished_v1(
        &mut self,
        context: &mut RuntimeContextV1<B>,
        budget: usize,
    ) {
        if context.is_terminal() {
            return;
        }
        let mut index = 0;
        for _ in 0..budget.min(self.entries.len()) {
            let result = catch_unwind(AssertUnwindSafe(|| {
                let retired = self
                    .entries
                    .get_mut(index)
                    .expect("bounded retirement roster")
                    .driver
                    .retire_unpublished(context)?;
                if context.is_terminal() {
                    return Err(crate::RuntimeValidationErrorV1::ContextTerminal.into());
                }
                if retired {
                    let entry = self
                        .entries
                        .remove(index)
                        .expect("retired unpublished owner");
                    self.retire_stream(entry.stream);
                    drop(entry);
                } else {
                    // Progress owns round-robin rotation. Rotating again here
                    // can starve both scans when their equal budgets alias.
                    index += 1;
                }
                Ok::<_, RuntimeErrorV1<B::Error>>(())
            }));
            match result {
                Ok(Ok(())) if !context.is_terminal() => {}
                failed => {
                    if let Err(payload) = failed {
                        core::mem::forget(payload);
                    }
                    context.quarantine_after_async_command_panic_v1();
                    return;
                }
            }
        }
    }

    pub(super) fn dispose_quiescent(&mut self) {
        // Pop one at a time so outer panic containment retains every later owner.
        while let Some(entry) = self.entries.pop_front() {
            drop(entry);
        }
        while let Some(entry) = self.parked.pop_front() {
            drop(entry);
        }
        self.streams.clear();
    }
}

type Submit<B, A> = Box<
    dyn FnOnce(
            &mut RuntimeContextV1<B>,
        )
            -> Result<RuntimeSubmissionV1<A>, RuntimeErrorV1<<B as RuntimeBackendV1>::Error>>
        + Send,
>;

struct Operation<B: RuntimeBackendV1, A> {
    stream: RuntimeStreamIdV1,
    submit: Option<Submit<B, A>>,
    submission: Option<RuntimeSubmissionV1<A>>,
    reply: Option<owned::Reply<RuntimeAsyncOperationResultV1<A, B::Error>>>,
    rejected_observations: u64,
    last_rejected_observation: Option<B::Error>,
    control: Option<RuntimeAsyncOperationControlV1>,
}

impl<B: RuntimeBackendV1, A> Operation<B, A> {
    fn finish(&mut self, observation: Result<RuntimeCompletionStatusV1, RuntimeErrorV1<B::Error>>) {
        if let Some(control) = &self.control {
            control.finish_observation();
        }
        if let Some(mut reply) = self.reply.take() {
            reply.complete(Ok(RuntimeAsyncOperationResultV1 {
                submission: self.submission.take(),
                observation,
                rejected_observations: self.rejected_observations,
                last_rejected_observation: self.last_rejected_observation.take(),
            }));
        }
    }
}

impl<B: RuntimeBackendV1, A> Drop for Operation<B, A> {
    fn drop(&mut self) {
        factory::stop_reply(
            &mut self.reply,
            self.control.as_ref(),
            RuntimeAsyncEngineCallErrorV1::EngineStopped,
        );
    }
}

impl<B: RuntimeBackendV1, A> EngineOperationV1<B> for Operation<B, A> {
    fn advance(&mut self, context: &mut RuntimeContextV1<B>) -> bool {
        if let Some(submit) = self.submit.take() {
            if let Some(control) = &self.control
                && !control.start_submission()
            {
                let error =
                    if control.phase() == RuntimeAsyncOperationPhaseV1::CancelledBeforeSubmission {
                        RuntimeAsyncEngineCallErrorV1::CancelledBeforeSubmission
                    } else {
                        RuntimeAsyncEngineCallErrorV1::EngineStopped
                    };
                factory::stop_reply(&mut self.reply, self.control.as_ref(), error);
                return true;
            }
            match submit(context) {
                Ok(submission) => {
                    self.submission = Some(submission);
                    if let Some(control) = &self.control {
                        control.observing();
                    }
                }
                Err(error) => {
                    self.finish(Err(error));
                    return true;
                }
            }
            return false;
        }
        let submission = self
            .submission
            .as_mut()
            .expect("accepted operation retains submission");
        let observation = match context.poll(submission) {
            Ok(_) => context
                .query_submission(submission)
                .map_err(RuntimeErrorV1::from),
            Err(error) => Err(error),
        };
        match classify_completion_v1(&observation) {
            CompletionClassV1::Pending => false,
            CompletionClassV1::Rejected => {
                let Err(RuntimeErrorV1::BackendRejected(error)) = observation else {
                    unreachable!("classifier preserves rejected observation");
                };
                self.rejected_observations = self.rejected_observations.saturating_add(1);
                self.last_rejected_observation = Some(error);
                false
            }
            CompletionClassV1::SuccessCandidate
            | CompletionClassV1::Failed(_)
            | CompletionClassV1::QuiescentWithoutResult
            | CompletionClassV1::QuiescentError
            | CompletionClassV1::Terminal
            | CompletionClassV1::ObservationError => {
                self.finish(observation);
                true
            }
        }
    }

    fn stream(&self) -> Option<RuntimeStreamIdV1> {
        Some(self.stream)
    }

    fn reject(&mut self, error: RuntimeAsyncEngineCallErrorV1) {
        let discard_unissued = matches!(
            error,
            RuntimeAsyncEngineCallErrorV1::EngineStopped
                | RuntimeAsyncEngineCallErrorV1::CommandPanicked
        );
        factory::stop_reply(&mut self.reply, self.control.as_ref(), error);
        if discard_unissued {
            // This ordinary driver retains only an unissued host callback here;
            // possibly live native resources remain owned by the Context.
            drop(self.submit.take());
        }
    }
}

impl<B: RuntimeBackendV1 + 'static> RuntimeAsyncProgressHandleV1<B> {
    fn operation_dependencies(
        &self,
        dependencies: Vec<RuntimeEventIdV1>,
    ) -> Result<snapshot::Charged<Box<[RuntimeEventIdV1]>>, RuntimeAsyncEngineCallErrorV1> {
        if self.observer.is_worker_thread() {
            return Err(RuntimeAsyncEngineCallErrorV1::ReentrantCall);
        }
        snapshot::charge_dependencies(&self.observer.snapshot_budget, dependencies)
    }

    pub(super) fn enqueue_operation<A: 'static>(
        &self,
        stream: RuntimeStreamIdV1,
        submit: Submit<B, A>,
    ) -> Result<RuntimeAsyncOperationFutureV1<A, B::Error>, RuntimeAsyncEngineCallErrorV1> {
        self.enqueue_controlled_operation(stream, submit, None)
    }

    pub(super) fn enqueue_tracked_operation<A: 'static>(
        &self,
        stream: RuntimeStreamIdV1,
        submit: Submit<B, A>,
    ) -> Result<RuntimeAsyncTrackedOperationV1<A, B::Error>, RuntimeAsyncEngineCallErrorV1> {
        let control = RuntimeAsyncOperationControlV1::new();
        let future = self.enqueue_controlled_operation(stream, submit, Some(control.clone()))?;
        Ok(RuntimeAsyncTrackedOperationV1 { future, control })
    }

    fn enqueue_controlled_operation<A: 'static>(
        &self,
        stream: RuntimeStreamIdV1,
        submit: Submit<B, A>,
        control: Option<RuntimeAsyncOperationControlV1>,
    ) -> Result<RuntimeAsyncOperationFutureV1<A, B::Error>, RuntimeAsyncEngineCallErrorV1> {
        if self.observer.is_worker_thread() {
            return Err(RuntimeAsyncEngineCallErrorV1::ReentrantCall);
        }
        let (reply, future) = owned::Reply::budgeted_pair(&self.observer.reply_budget)?;
        let factory = factory::OperationFactoryV1::new(stream, submit, reply, control);
        match self
            .observer
            .try_send_command(RuntimeAsyncEngineCommandV1::Operation(Box::new(factory)))
        {
            Ok(()) => Ok(future),
            Err(TrySendError::Full(_)) => Err(RuntimeAsyncEngineCallErrorV1::CommandQueueFull),
            Err(TrySendError::Disconnected(_)) => Err(RuntimeAsyncEngineCallErrorV1::EngineStopped),
        }
    }

    /// Enqueues a typed launch through the existing context admission path.
    ///
    /// Registry capacity is reserved before submission. The engine retains and
    /// advances accepted work even if this future is dropped. At most
    /// `waiter_capacity` operations occupy this independent registry; each tick
    /// advances at most `polls_per_tick` and flushes at most `flushes_per_tick`
    /// distinct operation streams, in addition to the observer registries.
    /// Arguments and kernel ownership remain subject to their existing contracts;
    /// these record bounds do not bound arbitrary user-owned argument bytes.
    /// Dependency lists are checked, compacted and charged before enqueue.
    /// Use `enqueue_launch` for a fully frozen, payload-budgeted launch request.
    pub fn launch<A: RuntimeArgumentsV1>(
        &self,
        stream: RuntimeStreamIdV1,
        kernel: Arc<TypedRuntimeKernelV1<A>>,
        arguments: A,
        geometry: RuntimeLaunchGeometryV1,
        dependencies: Vec<RuntimeEventIdV1>,
    ) -> Result<RuntimeAsyncOperationFutureV1<A, B::Error>, RuntimeAsyncEngineCallErrorV1> {
        let dependencies = self.operation_dependencies(dependencies)?;
        self.enqueue_operation(
            stream,
            Box::new(move |context| {
                dependencies.with(|dependencies| {
                    context.launch(stream, &kernel, &arguments, geometry, dependencies)
                })
            }),
        )
    }

    /// Like `launch`, with local identity, pre-submission cancellation, and
    /// recoverable timeout observation. It uses the same admission and registry.
    pub fn launch_tracked<A: RuntimeArgumentsV1>(
        &self,
        stream: RuntimeStreamIdV1,
        kernel: Arc<TypedRuntimeKernelV1<A>>,
        arguments: A,
        geometry: RuntimeLaunchGeometryV1,
        dependencies: Vec<RuntimeEventIdV1>,
    ) -> Result<RuntimeAsyncTrackedOperationV1<A, B::Error>, RuntimeAsyncEngineCallErrorV1> {
        let dependencies = self.operation_dependencies(dependencies)?;
        self.enqueue_tracked_operation(
            stream,
            Box::new(move |context| {
                dependencies.with(|dependencies| {
                    context.launch(stream, &kernel, &arguments, geometry, dependencies)
                })
            }),
        )
    }

    /// Enqueues a same-device transfer with runtime-owned progress and custody.
    pub fn copy_async(
        &self,
        stream: RuntimeStreamIdV1,
        source: RuntimeMemoryRegionV1,
        destination: RuntimeMemoryRegionV1,
        dependencies: Vec<RuntimeEventIdV1>,
    ) -> Result<RuntimeAsyncOperationFutureV1<RuntimeCopyV1, B::Error>, RuntimeAsyncEngineCallErrorV1>
    where
        B: RuntimeAsyncCopyBackendV1,
    {
        let dependencies = self.operation_dependencies(dependencies)?;
        self.enqueue_operation(
            stream,
            Box::new(move |context| {
                dependencies.with(|dependencies| {
                    context.copy_async(stream, source, destination, dependencies)
                })
            }),
        )
    }

    /// Same-device transfer with the same control and custody as `launch_tracked`.
    pub fn copy_async_tracked(
        &self,
        stream: RuntimeStreamIdV1,
        source: RuntimeMemoryRegionV1,
        destination: RuntimeMemoryRegionV1,
        dependencies: Vec<RuntimeEventIdV1>,
    ) -> Result<
        RuntimeAsyncTrackedOperationV1<RuntimeCopyV1, B::Error>,
        RuntimeAsyncEngineCallErrorV1,
    >
    where
        B: RuntimeAsyncCopyBackendV1,
    {
        let dependencies = self.operation_dependencies(dependencies)?;
        self.enqueue_tracked_operation(
            stream,
            Box::new(move |context| {
                dependencies.with(|dependencies| {
                    context.copy_async(stream, source, destination, dependencies)
                })
            }),
        )
    }

    /// Enqueues an admitted peer transfer; it does not imply native XGMI routing.
    pub fn peer_copy(
        &self,
        stream: RuntimeStreamIdV1,
        source: RuntimeMemoryRegionV1,
        destination: RuntimeMemoryRegionV1,
        dependencies: Vec<RuntimeEventIdV1>,
    ) -> Result<
        RuntimeAsyncOperationFutureV1<RuntimePeerCopyV1, B::Error>,
        RuntimeAsyncEngineCallErrorV1,
    > {
        let dependencies = self.operation_dependencies(dependencies)?;
        self.enqueue_operation(
            stream,
            Box::new(move |context| {
                dependencies.with(|dependencies| {
                    context.peer_copy(stream, source, destination, dependencies)
                })
            }),
        )
    }

    /// Admitted peer transfer with local control; it does not imply XGMI routing.
    pub fn peer_copy_tracked(
        &self,
        stream: RuntimeStreamIdV1,
        source: RuntimeMemoryRegionV1,
        destination: RuntimeMemoryRegionV1,
        dependencies: Vec<RuntimeEventIdV1>,
    ) -> Result<
        RuntimeAsyncTrackedOperationV1<RuntimePeerCopyV1, B::Error>,
        RuntimeAsyncEngineCallErrorV1,
    > {
        let dependencies = self.operation_dependencies(dependencies)?;
        self.enqueue_tracked_operation(
            stream,
            Box::new(move |context| {
                dependencies.with(|dependencies| {
                    context.peer_copy(stream, source, destination, dependencies)
                })
            }),
        )
    }
}

pub(super) fn advance_operations_v1<B: RuntimeBackendV1>(
    context: &mut RuntimeContextV1<B>,
    operations: &mut OperationRegistryV1<B>,
    poll_budget: usize,
    flush_budget: usize,
    flush: RuntimeAsyncFlushDriverV1<B>,
) {
    for _ in 0..poll_budget.min(operations.active_len()) {
        let entry = operations
            .entries
            .front_mut()
            .expect("bounded operation roster");
        // An adapter may have performed a side effect before unwinding. Do not
        // let command panic containment turn that into permission to retry.
        match catch_unwind(AssertUnwindSafe(|| {
            let retired = entry.driver.advance(context);
            (retired, !retired && entry.driver.prepared_key().is_some())
        })) {
            Ok(_) if context.is_terminal() => return,
            Ok((true, _)) => {
                let retired = operations.entries.pop_front().expect("retired driver");
                operations.retire_stream(retired.stream);
            }
            Ok((false, false)) => operations.entries.rotate_left(1),
            Ok((false, true)) => {
                let parked = operations.entries.pop_front().expect("prepared driver");
                operations.retire_stream(parked.stream);
                operations.parked.push_back(parked);
                let entry = operations.parked.back_mut().expect("parked driver");
                if let Err(payload) = catch_unwind(AssertUnwindSafe(|| {
                    entry.driver.complete_preparation();
                })) {
                    core::mem::forget(payload);
                    context.quarantine_after_async_command_panic_v1();
                    if let Err(payload) = catch_unwind(AssertUnwindSafe(|| {
                        entry
                            .driver
                            .reject(RuntimeAsyncEngineCallErrorV1::CommandPanicked);
                    })) {
                        core::mem::forget(payload);
                    }
                    return;
                }
            }
            Err(payload) => {
                core::mem::forget(payload);
                context.quarantine_after_async_command_panic_v1();
                if let Err(payload) = catch_unwind(AssertUnwindSafe(|| {
                    entry
                        .driver
                        .reject(RuntimeAsyncEngineCallErrorV1::CommandPanicked);
                })) {
                    core::mem::forget(payload);
                }
                return;
            }
        }
        if context.is_terminal() {
            return;
        }
    }
    let selected: Vec<_> = match operations.flush_cursor {
        Some(cursor) => operations
            .streams
            .range((Excluded(cursor), Unbounded))
            .chain(operations.streams.range(..=cursor))
            .map(|(stream, _)| *stream)
            .take(flush_budget)
            .collect(),
        None => operations
            .streams
            .keys()
            .copied()
            .take(flush_budget)
            .collect(),
    };
    for stream in selected {
        operations.flush_cursor = Some(stream);
        match catch_unwind(AssertUnwindSafe(|| flush(context, stream))) {
            Ok(Err(error)) if runtime_error_is_terminal_v1(&error) => return,
            Err(payload) => {
                core::mem::forget(payload);
                context.quarantine_after_async_command_panic_v1();
                return;
            }
            _ => {}
        }
    }
}

//! Owner-thread construction and nonblocking commands. No backend crosses threads.

use super::*;
use crate::{RuntimeBackendFailureV1, RuntimeCleanupReportV1, RuntimeOwnedShutdownBackendV1};

struct ReplyState<R> {
    result: Option<Result<R, RuntimeAsyncEngineCallErrorV1>>,
    waker: Option<Waker>,
    // The retained result and waker drop before returning the cell's count credit.
    _permit: Option<reply_budget::ReplyPermitV1>,
}

pub(super) struct Reply<R> {
    state: Arc<Mutex<ReplyState<R>>>,
    completed: bool,
}

impl<R> Reply<R> {
    pub(super) fn pair() -> (Self, RuntimeAsyncCommandFutureV1<R>) {
        Self::with_permit(None)
    }

    pub(super) fn budgeted_pair(
        budget: &Arc<reply_budget::ReplyBudgetV1>,
    ) -> Result<(Self, RuntimeAsyncCommandFutureV1<R>), RuntimeAsyncEngineCallErrorV1> {
        Ok(Self::with_permit(Some(budget.reserve()?)))
    }

    fn with_permit(
        permit: Option<reply_budget::ReplyPermitV1>,
    ) -> (Self, RuntimeAsyncCommandFutureV1<R>) {
        let state = Arc::new(Mutex::new(ReplyState {
            result: None,
            waker: None,
            _permit: permit,
        }));
        (
            Self {
                state: Arc::clone(&state),
                completed: false,
            },
            RuntimeAsyncCommandFutureV1 {
                state,
                completed: false,
            },
        )
    }

    pub(super) fn complete(&mut self, result: Result<R, RuntimeAsyncEngineCallErrorV1>) {
        if !fe2o3_runtime_model::r61_reply_may_resolve_v1(self.completed) {
            return;
        }
        self.completed = true;
        let waker = {
            let mut state = self.state.lock().unwrap_or_else(|error| error.into_inner());
            state.result = Some(result);
            state.waker.take()
        };
        if let Some(waker) = waker
            && let Err(payload) = catch_unwind(AssertUnwindSafe(|| waker.wake()))
        {
            core::mem::forget(payload);
        }
    }
}

impl<R> Drop for Reply<R> {
    fn drop(&mut self) {
        self.complete(Err(RuntimeAsyncEngineCallErrorV1::EngineStopped));
    }
}

/// Result of one boundedly enqueued context command, not GPU completion.
///
/// Dropping this future does not withdraw the command or release runtime custody.
/// A command discarded during shutdown resolves as `EngineStopped`.
#[must_use = "dropping the response does not cancel the accepted command"]
pub struct RuntimeAsyncCommandFutureV1<R> {
    state: Arc<Mutex<ReplyState<R>>>,
    completed: bool,
}

fn discard_waker(waker: Option<Waker>) {
    if let Err(payload) = catch_unwind(AssertUnwindSafe(|| drop(waker))) {
        core::mem::forget(payload);
    }
}

impl<R> RuntimeAsyncCommandFutureV1<R> {
    pub(super) fn clear_waker(&self) {
        let waker = self
            .state
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .waker
            .take();
        discard_waker(waker);
    }
}

impl<R> Future for RuntimeAsyncCommandFutureV1<R> {
    type Output = Result<R, RuntimeAsyncEngineCallErrorV1>;

    fn poll(mut self: Pin<&mut Self>, context: &mut Context<'_>) -> Poll<Self::Output> {
        assert!(
            !self.completed,
            "runtime command future polled after completion"
        );
        // Executor-supplied clone/drop callbacks must not run under our lock.
        let mut new_waker = Some(context.waker().clone());
        let (result, old_waker) = {
            let mut state = self.state.lock().unwrap_or_else(|error| error.into_inner());
            let result = state.result.take();
            let old_waker = if result.is_none() {
                core::mem::replace(&mut state.waker, new_waker.take())
            } else {
                state.waker.take()
            };
            (result, old_waker)
        };
        discard_waker(old_waker);
        discard_waker(new_waker);
        match result {
            Some(result) => {
                self.completed = true;
                Poll::Ready(result)
            }
            None => Poll::Pending,
        }
    }
}

impl<R> Drop for RuntimeAsyncCommandFutureV1<R> {
    fn drop(&mut self) {
        self.clear_waker();
    }
}

impl<B: RuntimeBackendV1 + 'static> RuntimeAsyncEngineHandleV1<B> {
    /// Enqueues a command without waiting for the owner thread to execute it.
    ///
    /// The bounded channel rejects immediately when full. The closure must use
    /// nonblocking runtime operations to preserve progress fairness. As with
    /// `try_with_context`, returning a submission means accepted custody, not
    /// completion. Local command captures are not a serialized transport API.
    pub fn enqueue_with_context<R, F>(
        &self,
        operation: F,
    ) -> Result<RuntimeAsyncCommandFutureV1<R>, RuntimeAsyncEngineCallErrorV1>
    where
        R: Send + 'static,
        F: FnOnce(&mut RuntimeContextV1<B>) -> R + Send + 'static,
    {
        if self.is_worker_thread() {
            return Err(RuntimeAsyncEngineCallErrorV1::ReentrantCall);
        }
        let (mut reply, future) = Reply::budgeted_pair(&self.reply_budget)?;
        let quarantine_command_panics = self.quarantine_command_panics;
        let command = RuntimeAsyncEngineCommandV1::Context(Box::new(move |context| {
            let result = catch_unwind(AssertUnwindSafe(|| operation(context))).map_err(|payload| {
                core::mem::forget(payload);
                if quarantine_command_panics {
                    context.quarantine_after_async_command_panic_v1();
                }
                RuntimeAsyncEngineCallErrorV1::CommandPanicked
            });
            reply.complete(result);
        }));
        match self.try_send_command(command) {
            Ok(()) => Ok(future),
            Err(TrySendError::Full(_)) => Err(RuntimeAsyncEngineCallErrorV1::CommandQueueFull),
            Err(TrySendError::Disconnected(_)) => Err(RuntimeAsyncEngineCallErrorV1::EngineStopped),
        }
    }
}

/// Failure before an owner-thread context becomes available.
#[derive(Debug)]
pub enum RuntimeAsyncOwnedSpawnErrorV1<E> {
    InvalidEngineConfig(RuntimeAsyncEngineConfigErrorV1),
    InvalidProgressConfig(RuntimeAsyncProgressConfigErrorV1),
    CaptureBudget(fe2o3_resource_accounting::ResourceCreditErrorV1),
    Thread(io::Error),
    Initialize(E),
    InitializerPanicked,
}

impl<E: fmt::Display> fmt::Display for RuntimeAsyncOwnedSpawnErrorV1<E> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidEngineConfig(error) => error.fmt(formatter),
            Self::InvalidProgressConfig(error) => error.fmt(formatter),
            Self::CaptureBudget(error) => error.fmt(formatter),
            Self::Thread(error) => write!(formatter, "runtime owner thread: {error}"),
            Self::Initialize(error) => write!(formatter, "runtime owner initialization: {error}"),
            Self::InitializerPanicked => formatter.write_str("runtime owner initializer panicked"),
        }
    }
}

impl<E: Error + 'static> Error for RuntimeAsyncOwnedSpawnErrorV1<E> {}

/// Owner-thread shutdown disposition. Quarantine never asserts quiescence.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RuntimeAsyncOwnedDispositionV1 {
    Released,
    /// The complete owning context was deliberately retained until process exit.
    RetainedUntilProcessExit,
}

/// Exact cleanup report, or no report if an adapter panicked before returning one.
#[derive(Debug)]
pub struct RuntimeAsyncOwnedShutdownV1<E> {
    pub disposition: RuntimeAsyncOwnedDispositionV1,
    pub cleanup: Option<RuntimeCleanupReportV1<E>>,
    pub worker_panicked: bool,
    pub native_failure: Option<RuntimeBackendFailureV1<E>>,
}

/// One progress thread which creates, uses, and retires even a `!Send` backend.
///
/// Only factories, commands, observations, and cleanup reports cross threads.
/// Shutdown stops observation, then runs the existing context cleanup once on
/// its owner thread. Failed cleanup or an adapter panic retains the entire
/// context until process exit; it cannot be recovered on the caller thread.
/// Command panics also seal the context because a callback may have reached an
/// adapter before unwinding. The factory remains responsible for cleanup and
/// panic custody until it successfully returns its complete context.
/// Use an isolated process when that terminal retention policy is required to
/// be reclaimable. This API does not grant device or executable authority.
///
/// ```compile_fail
/// use fe2o3_runtime::{KfdRuntimeBackendV1, RuntimeAsyncOwnedEngineV1};
/// fn require_send<T: Send>() {}
/// require_send::<RuntimeAsyncOwnedEngineV1<KfdRuntimeBackendV1>>();
/// ```
#[must_use = "the owner must be shut down to inspect cleanup and quarantine"]
pub struct RuntimeAsyncOwnedEngineV1<B: RuntimeBackendV1 + 'static> {
    admission: Arc<drain::AdmissionV1>,
    sender: Option<SyncSender<RuntimeAsyncEngineCommandV1<B>>>,
    worker: Option<JoinHandle<RuntimeAsyncOwnedShutdownV1<B::Error>>>,
    thread_affinity: PhantomData<Rc<()>>,
}

impl<B: RuntimeBackendV1 + 'static> RuntimeAsyncOwnedEngineV1<B> {
    pub fn spawn_with_progress<F, E>(
        factory: F,
        config: RuntimeAsyncEngineConfigV1,
        progress_config: RuntimeAsyncProgressConfigV1,
    ) -> Result<(Self, RuntimeAsyncProgressHandleV1<B>), RuntimeAsyncOwnedSpawnErrorV1<E>>
    where
        B: RuntimeFlushBackendV1 + RuntimeOwnedShutdownBackendV1,
        F: FnOnce() -> Result<RuntimeContextV1<B>, E> + Send + 'static,
        E: Send + 'static,
    {
        RuntimeAsyncEngineConfigV1::new(
            config.command_capacity,
            config.waiter_capacity,
            config.commands_per_tick,
            config.polls_per_tick,
            config.poll_interval,
        )
        .and_then(|validated| validated.with_snapshot_byte_capacity(config.snapshot_byte_capacity))
        .and_then(|validated| validated.with_reply_capacity(config.reply_capacity))
        .and_then(|validated| {
            validated.with_drain_capture_byte_capacity(config.drain_capture_byte_capacity)
        })
        .map_err(RuntimeAsyncOwnedSpawnErrorV1::InvalidEngineConfig)?;
        RuntimeAsyncProgressConfigV1::new(
            progress_config.stream_capacity,
            progress_config.flushes_per_tick,
        )
        .map_err(RuntimeAsyncOwnedSpawnErrorV1::InvalidProgressConfig)?;
        let capture_budget = config
            .capture_budget_v1()
            .map_err(RuntimeAsyncOwnedSpawnErrorV1::CaptureBudget)?;
        let (sender, receiver) = sync_channel(config.command_capacity);
        let admission = drain::AdmissionV1::new();
        let worker_admission = Arc::clone(&admission);
        let (startup_sender, startup_receiver) = sync_channel(1);
        let worker_thread = Arc::new(OnceLock::new());
        let worker_id = Arc::clone(&worker_thread);
        let worker = thread::Builder::new()
            .name("fe2o3-runtime-owner-v1".into())
            .spawn(move || {
                worker_id
                    .set(thread::current().id())
                    .expect("one owner thread");
                // Reserve the bounded roster before constructing native custody.
                let operations = operation::OperationRegistryV1::new(config.waiter_capacity, true);
                let mut context = match catch_unwind(AssertUnwindSafe(factory)) {
                    Ok(Ok(context)) => context,
                    Ok(Err(error)) => {
                        let _ = startup_sender
                            .send(Err(RuntimeAsyncOwnedSpawnErrorV1::Initialize(error)));
                        return RuntimeAsyncOwnedShutdownV1 {
                            disposition: RuntimeAsyncOwnedDispositionV1::Released,
                            cleanup: None,
                            worker_panicked: false,
                            native_failure: None,
                        };
                    }
                    Err(payload) => {
                        core::mem::forget(payload);
                        let _ = startup_sender
                            .send(Err(RuntimeAsyncOwnedSpawnErrorV1::InitializerPanicked));
                        return RuntimeAsyncOwnedShutdownV1 {
                            // No context was returned to engine ownership.
                            disposition: RuntimeAsyncOwnedDispositionV1::Released,
                            cleanup: None,
                            worker_panicked: true,
                            native_failure: None,
                        };
                    }
                };
                let _ = startup_sender.send(Ok(context.capture_context_generation_v1()));
                // Rebind after Context for successful drop order, outside the
                // unwind boundary so both owners survive failed native shutdown.
                let mut operations = operations;
                let outcome = catch_unwind(AssertUnwindSafe(|| {
                    run_engine_context_v1(
                        &mut context,
                        &mut operations,
                        receiver,
                        config,
                        Some(RuntimeAsyncProgressModeV1 {
                            config: progress_config,
                            flush_stream: flush_stream_v1::<B>,
                        }),
                        worker_admission,
                    );
                    operations.retire_unpublished_v1(&mut context, usize::MAX);
                    let cleanup = context.cleanup();
                    let native_failure = if cleanup.is_complete() {
                        context.shutdown_owned_backend_v1().err()
                    } else {
                        None
                    };
                    if cleanup.is_complete() && native_failure.is_none() {
                        operations.dispose_quiescent();
                    }
                    (cleanup, native_failure)
                }));
                match outcome {
                    Ok((cleanup, None))
                        if fe2o3_runtime_model::r61_owner_may_release_v1(
                            fe2o3_runtime_model::R61ShutdownFactsV1 {
                                worker_returned_normally: true,
                                context_cleanup_complete: cleanup.is_complete(),
                                native_shutdown_attempted: cleanup.is_complete(),
                                native_shutdown_succeeded: cleanup.is_complete(),
                            },
                        ) =>
                    {
                        RuntimeAsyncOwnedShutdownV1 {
                            disposition: RuntimeAsyncOwnedDispositionV1::Released,
                            cleanup: Some(cleanup),
                            worker_panicked: false,
                            native_failure: None,
                        }
                    }
                    Ok((cleanup, native_failure)) => {
                        core::mem::forget(operations);
                        core::mem::forget(context);
                        RuntimeAsyncOwnedShutdownV1 {
                            disposition: RuntimeAsyncOwnedDispositionV1::RetainedUntilProcessExit,
                            cleanup: Some(cleanup),
                            worker_panicked: false,
                            native_failure,
                        }
                    }
                    Err(payload) => {
                        core::mem::forget(payload);
                        operations.stop_observations();
                        core::mem::forget(operations);
                        core::mem::forget(context);
                        RuntimeAsyncOwnedShutdownV1 {
                            disposition: RuntimeAsyncOwnedDispositionV1::RetainedUntilProcessExit,
                            cleanup: None,
                            worker_panicked: true,
                            native_failure: None,
                        }
                    }
                }
            })
            .map_err(RuntimeAsyncOwnedSpawnErrorV1::Thread)?;
        let context_generation = match startup_receiver
            .recv()
            .unwrap_or(Err(RuntimeAsyncOwnedSpawnErrorV1::InitializerPanicked))
        {
            Ok(generation) => generation,
            Err(error) => {
                let _ = worker.join();
                return Err(error);
            }
        };
        let observer = RuntimeAsyncEngineHandleV1 {
            context_generation,
            capture_budget,
            reply_budget: reply_budget::ReplyBudgetV1::new(config.reply_capacity),
            admission: Arc::clone(&admission),
            snapshot_budget: snapshot::SnapshotBudgetV1::new(config.snapshot_byte_capacity),
            graph_slot: Arc::new(AtomicBool::new(false)),
            sender: sender.clone(),
            worker_thread,
            quarantine_command_panics: true,
        };
        Ok((
            Self {
                admission,
                sender: Some(sender),
                worker: Some(worker),
                thread_affinity: PhantomData,
            },
            RuntimeAsyncProgressHandleV1 { observer },
        ))
    }

    pub fn shutdown(
        mut self,
    ) -> Result<RuntimeAsyncOwnedShutdownV1<B::Error>, RuntimeAsyncEngineJoinErrorV1> {
        self.stop_and_join()
    }

    fn stop_and_join(
        &mut self,
    ) -> Result<RuntimeAsyncOwnedShutdownV1<B::Error>, RuntimeAsyncEngineJoinErrorV1> {
        self.admission.close();
        if let Some(sender) = self.sender.take() {
            let _ = sender.send(RuntimeAsyncEngineCommandV1::Stop);
        }
        self.worker
            .take()
            .ok_or(RuntimeAsyncEngineJoinErrorV1::AlreadyStopped)?
            .join()
            .map_err(|payload| {
                core::mem::forget(payload);
                RuntimeAsyncEngineJoinErrorV1::WorkerPanicked
            })
    }
}

impl<B: RuntimeBackendV1 + 'static> Drop for RuntimeAsyncOwnedEngineV1<B> {
    fn drop(&mut self) {
        let _ = self.stop_and_join();
    }
}

use super::*;
use crate::{RuntimeAccessV1, RuntimeMemoryRegionV1};
use crate::{RuntimeGfx942GeneratedReservationErrorV1, RuntimeValidationErrorV1};
use generated_operation::adoption::{ActivationErrorV1, AdoptionHooksV1};

struct Payload {
    _local: LocalPayload,
    source: Vec<u8>,
    readback: Vec<u8>,
    pointers: (usize, usize),
    state: Arc<Mutex<MockState>>,
    mode: u8,
    stream: Option<RuntimeStreamIdV1>,
}

impl Drop for Payload {
    fn drop(&mut self) {
        let mut state = self.state.lock().unwrap();
        state.adoption_order.push("payload_drop");
        state
            .adoption_payload_drops
            .push((self.stream, thread::current().id()));
    }
}

pub(super) trait RetireBackend: RuntimeBackendV1<Error = MockError> {
    fn retire_adoption(
        &mut self,
        stream: RuntimeStreamIdV1,
    ) -> Result<(), RuntimeErrorV1<MockError>>;
}

fn retire(
    state: &Mutex<MockState>,
    stream: RuntimeStreamIdV1,
) -> Result<(), RuntimeErrorV1<MockError>> {
    let mode = {
        let mut state = state.lock().unwrap();
        state.adoption_retire_calls += 1;
        state.adoption_order.push("retire");
        state
            .adoption_retire_attempts
            .push((stream, thread::current().id()));
        state
            .adoption_retire_modes
            .get(&stream)
            .copied()
            .unwrap_or(state.adoption_retire_mode)
    };
    match mode {
        1 => Err(RuntimeValidationErrorV1::Unsupported.into()),
        2 => panic!("retirement panic after simulated disposal"),
        _ => Ok(()),
    }
}

impl RetireBackend for MockBackend {
    fn retire_adoption(
        &mut self,
        stream: RuntimeStreamIdV1,
    ) -> Result<(), RuntimeErrorV1<MockError>> {
        retire(&self.state, stream)
    }
}
impl RetireBackend for ThreadBoundBackend {
    fn retire_adoption(
        &mut self,
        stream: RuntimeStreamIdV1,
    ) -> Result<(), RuntimeErrorV1<MockError>> {
        self.record("adoption_retire");
        retire(&self.inner.state, stream)
    }
}

fn reserve<B: RuntimeBackendV1>(
    _: &mut RuntimeContextV1<B>,
    payload: &mut Payload,
) -> Result<crate::generated_source::GeneratedHostRosterV1, RuntimeGfx942GeneratedReservationErrorV1>
{
    payload.readback = vec![0; payload.source.len()];
    payload.pointers = (
        payload.source.as_ptr() as usize,
        payload.readback.as_ptr() as usize,
    );
    Ok(reservation_tests::roster())
}

fn hooks<B: RetireBackend>() -> AdoptionHooksV1<B, Payload> {
    AdoptionHooksV1 {
        preflight: |context, payload, _, _| {
            payload
                .state
                .lock()
                .unwrap()
                .adoption_order
                .push("preflight");
            match payload.mode {
                1 => Err(RuntimeValidationErrorV1::Unsupported.into()),
                2 => panic!("adoption preflight panic"),
                5 => {
                    context.quarantine_after_async_command_panic_v1();
                    Ok(())
                }
                _ => Ok(()),
            }
        },
        adopt: |context, payload, roster, hold| {
            payload.stream = Some(hold.stream());
            payload.state.lock().unwrap().adoption_order.push("adopt");
            assert_eq!(roster.count, 1);
            assert_eq!(
                payload.pointers,
                (
                    payload.source.as_ptr() as usize,
                    payload.readback.as_ptr() as usize
                )
            );
            assert_eq!(payload.source, vec![7; 16]);
            assert!(matches!(
                context.destroy_stream(hold.stream()),
                Err(RuntimeErrorV1::Validation(
                    RuntimeValidationErrorV1::ContextReserved
                ))
            ));
            assert!(matches!(
                context.reserve_graph_v1(1),
                Err(RuntimeValidationErrorV1::ContextReserved)
            ));
            assert!(!context.cleanup().is_complete());
            match payload.mode {
                3 => Err(RuntimeValidationErrorV1::Unsupported.into()),
                4 => panic!("adoption panic after simulated acquisition"),
                _ => {
                    payload
                        .state
                        .lock()
                        .unwrap()
                        .adoption_completed
                        .push((hold.stream(), thread::current().id()));
                    Ok(())
                }
            }
        },
        // Also valid for the empty prefix when Stop preceded first advancement.
        retire: |context, hold| {
            context
                .backend_mut_for_test_v1()
                .retire_adoption(hold.stream())
        },
    }
}

pub(super) fn preparation<B: RetireBackend + 'static>(
    handle: &RuntimeAsyncProgressHandleV1<B>,
    state: Arc<Mutex<MockState>>,
    drops: Arc<AtomicUsize>,
    mode: u8,
    enabled: bool,
) -> RuntimeAsyncPreparationV1<()> {
    handle
        .enqueue_preparation_with_adoption_v1(
            Box::new(move |_| {
                Ok(Payload {
                    _local: LocalPayload {
                        local: Rc::new(Cell::new(0)),
                        drops,
                        owner: thread::current().id(),
                        panic_on_drop: false,
                    },
                    source: vec![7; 16],
                    readback: Vec::new(),
                    pointers: (0, 0),
                    state,
                    mode,
                    stream: None,
                })
            }),
            Some(reserve),
            enabled.then(hooks),
        )
        .unwrap()
}

pub(super) fn reserved(
    h: &mut Harness,
    drops: Arc<AtomicUsize>,
    mode: u8,
    enabled: bool,
) -> (RuntimeAsyncReservedTicketV1, RuntimeStreamIdV1) {
    let stream = h
        .context
        .create_stream(h.context.devices()[0].id())
        .unwrap();
    let future = preparation(&h.handle, h.state.clone(), drops, mode, enabled);
    h.command();
    h.advance();
    let ticket = ready(future).unwrap().unwrap();
    let future = h.handle.try_reserve_prepared_v1(ticket).unwrap();
    h.command();
    (ready(future).unwrap().unwrap(), stream)
}

pub(super) fn activate(
    h: &mut Harness,
    ticket: RuntimeAsyncReservedTicketV1,
    stream: RuntimeStreamIdV1,
) {
    let future = h.handle.try_activate_reserved_v1(ticket, stream).unwrap();
    assert!(!h.command());
    ready(future).unwrap().unwrap();
}

#[test]
fn adoption_preserves_owner_capacity_reply_and_never_flushes_or_discards() {
    let mut h = Harness::new(1, 2, true);
    let drops = Arc::new(AtomicUsize::new(0));
    let (ticket, stream) = reserved(&mut h, drops.clone(), 0, true);
    let key = ticket.key.clone();
    assert_eq!(h.handle.observer.reply_cells_in_use(), 1);
    activate(&mut h, ticket, stream);
    assert_eq!((h.registry.len(), h.registry.active_len()), (1, 1));
    assert_eq!(h.handle.observer.reply_cells_in_use(), 1);
    assert!(!h.registry.discard_reserved(&key));
    assert!(!h.registry.discard_prepared(&key));
    for _ in 0..4 {
        h.advance();
    }
    assert!(h.state.lock().unwrap().issues.is_empty());
    assert!(h.state.lock().unwrap().flush_calls.is_empty());
    assert_eq!(
        h.state.lock().unwrap().adoption_order,
        ["preflight", "adopt"]
    );
    assert_eq!(drops.load(Ordering::SeqCst), 0);
    h.registry.retire_unpublished_v1(&mut h.context, 1);
    assert_eq!(h.registry.len(), 0);
    assert_eq!(drops.load(Ordering::SeqCst), 1);
    assert_eq!(h.handle.observer.reply_cells_in_use(), 0);
    assert_eq!(
        h.state.lock().unwrap().adoption_order,
        ["preflight", "adopt", "retire", "payload_drop"]
    );
    h.context.destroy_stream(stream).unwrap();
}

#[test]
fn adoption_unsupported_and_preflight_rejection_recover_exact_ticket_without_hold() {
    for (enabled, mode) in [(false, 0), (true, 1)] {
        let mut h = Harness::new(1, 2, true);
        let drops = Arc::new(AtomicUsize::new(0));
        let (ticket, stream) = reserved(&mut h, drops.clone(), mode, enabled);
        let key = ticket.key.clone();
        let future = h.handle.try_activate_reserved_v1(ticket, stream).unwrap();
        assert!(!h.command());
        let failure = ready(future).unwrap().unwrap_err();
        assert!(Arc::ptr_eq(&key, &failure.ticket.key));
        assert!(matches!(
            failure.error,
            ActivationErrorV1::Context(RuntimeErrorV1::Validation(
                RuntimeValidationErrorV1::Unsupported
            ))
        ));
        assert_eq!((h.registry.len(), h.registry.active_len()), (1, 0));
        assert_eq!(h.handle.observer.reply_cells_in_use(), 1);
        assert_eq!(drops.load(Ordering::SeqCst), 0);
        h.context.destroy_stream(stream).unwrap();
        assert!(h.registry.discard_reserved(&key));
    }
}

#[test]
fn adoption_panic_terminal_preflight_and_post_effect_errors_never_retry_or_drop() {
    for mode in [2, 3, 4, 5] {
        let mut h = Harness::new(1, 2, true);
        let drops = Arc::new(AtomicUsize::new(0));
        let (ticket, stream) = reserved(&mut h, drops.clone(), mode, true);
        let key = ticket.key.clone();
        let future = h.handle.try_activate_reserved_v1(ticket, stream).unwrap();
        let stopped = h.command();
        if mode == 2 || mode == 5 {
            assert!(stopped);
            assert!(ready(future).is_err());
        } else {
            assert!(!stopped);
            ready(future).unwrap().unwrap();
            h.advance();
            assert!(!h.registry.discard_reserved(&key));
        }
        assert!(h.context.is_terminal());
        let before = h.state.lock().unwrap().adoption_order.clone();
        h.registry.retire_unpublished_v1(&mut h.context, 4);
        assert_eq!(h.state.lock().unwrap().adoption_order, before);
        assert_eq!(h.registry.len(), 1);
        assert_eq!(drops.load(Ordering::SeqCst), 0);
        assert!(!h.context.cleanup().is_complete());
        // This is a fake backend. Assert production retention before disposing
        // the test-only fixture; owned-engine tests exercise real quarantine.
    }
}

