}

impl<E> RuntimeCleanupFailureV1<E> {
    pub const fn resource(&self) -> RuntimeCleanupResourceV1 {
        self.resource
    }

    pub const fn failure(&self) -> &RuntimeBackendFailureV1<E> {
        &self.failure
    }
