        );
        let mut other = RuntimeContextV1::open(MockBackend::default()).unwrap();
        let foreign = other.reserve_graph_v1(1).unwrap();
        assert_eq!(
            context.close_graph_issue_v1(foreign),
            Err(RuntimeValidationErrorV1::ContextReserved)
