        ) -> Result<u64, RuntimeBackendFailureV1<Self::Error>> {
            let BackendSemanticLaunchV1::Atomic(contract) = launch.semantic_launch else {
                return Err(RuntimeBackendFailureV1::Rejected(MockError("not atomic")));
